using System.Data.Common;
using Careflow.Application;
using Careflow.Domain;
namespace Careflow.Infrastructure;

// SQL Server IHospitalStore slice for Phase 4: insurance/TPA, doctor incentives,
// telemedicine, inventory/procurement and CSSD.

public sealed partial class SqlHospitalStore
{
    private static DateOnly? DNDate(DbDataReader r, string col) => r[col] is DBNull ? null : DateOnly.FromDateTime(Convert.ToDateTime(r[col]));

    // ---- insurance ----------------------------------------------------------
    private static Payer MapPayer(DbDataReader r) => new(G(r, "Id"), S(r, "Code"), S(r, "Name"), S(r, "Contact"), B(r, "Active"));
    private static InsurancePlan MapPlan(DbDataReader r) => new(G(r, "Id"), G(r, "PayerId"), S(r, "Code"), S(r, "Name"), S(r, "PolicyType"), DN(r, "SumInsuredLimit")!.Value);
    private static Coverage MapCoverage(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "PatientId"), G(r, "PlanId"), S(r, "PolicyNumber"), S(r, "MemberId"), Date(r, "ValidFromDate"), Date(r, "ValidToDate"), DN(r, "SumInsured")!.Value, DN(r, "Deductible")!.Value, S(r, "Status"), L(r, "Version"));
    private static Preauthorization MapPreauth(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "CoverageId"), G(r, "PatientId"), S(r, "DiagnosisCode"), S(r, "ProcedureCode"), DN(r, "RequestedAmount")!.Value, S(r, "Status"), DNDate(r, "ValidFromDate"), DNDate(r, "ValidToDate"), r["ApprovedAmount"] is DBNull ? null : DN(r, "ApprovedAmount"), S(r, "ResponseNote"), GN(r, "RespondedBy"), TN(r, "RespondedAtUtc"), G(r, "RequestedBy"), T(r, "RequestedAtUtc"), L(r, "Version"));
    private static Claim MapClaim(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "PatientId"), G(r, "CoverageId"), GN(r, "InvoiceId"), GN(r, "AdmissionId"), S(r, "DiagnosisCode"), DN(r, "TotalAmount")!.Value, DN(r, "ApprovedAmount")!.Value, DN(r, "PatientLiability")!.Value, S(r, "Status"), S(r, "QueryNote"), S(r, "ResponseNote"), S(r, "RejectionReason"), GN(r, "SubmittedBy"), TN(r, "SubmittedAtUtc"), G(r, "CreatedBy"), T(r, "CreatedAtUtc"), L(r, "Version"));
    private static ClaimLine MapClaimLine(DbDataReader r) => new(G(r, "Id"), G(r, "ClaimId"), S(r, "ServiceCode"), S(r, "Description"), DN(r, "Quantity")!.Value, DN(r, "UnitPrice")!.Value, DN(r, "Amount")!.Value, DN(r, "ApprovedAmount")!.Value);
    private static ClaimQuery MapClaimQuery(DbDataReader r) => new(G(r, "Id"), G(r, "ClaimId"), S(r, "Question"), S(r, "Response"), G(r, "RaisedBy"), T(r, "RaisedAtUtc"), GN(r, "RespondedBy"), TN(r, "RespondedAtUtc"));
    private static Settlement MapSettlement(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "ClaimId"), DN(r, "Amount")!.Value, S(r, "Mode"), S(r, "Reference"), T(r, "SettledAtUtc"), G(r, "SettledBy"));

    public Task<IReadOnlyList<Payer>> ListPayersAsync(CancellationToken ct) => Query("SELECT Id,Code,Name,Contact,Active FROM insurance.Payers WHERE HospitalId=@h ORDER BY Name", MapPayer, H).ContinueWith(t => (IReadOnlyList<Payer>)t.Result, ct);
    public Task<Coverage?> FindCoverageAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,PlanId,PolicyNumber,MemberId,ValidFromDate,ValidToDate,SumInsured,Deductible,Status,Version FROM insurance.Coverages WHERE HospitalId=@h AND Id=@id", MapCoverage, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task<Coverage?> FindCoverageByPolicyAsync(Guid patientId, string policyNumber, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,PlanId,PolicyNumber,MemberId,ValidFromDate,ValidToDate,SumInsured,Deductible,Status,Version FROM insurance.Coverages WHERE HospitalId=@h AND PatientId=@patient AND PolicyNumber=@policy", MapCoverage, H, ("patient", patientId), ("policy", policyNumber)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertCoverageAsync(Coverage c, CancellationToken ct) => Execute("INSERT INTO insurance.Coverages(Id,HospitalId,BranchId,Number,PatientId,PlanId,PolicyNumber,MemberId,ValidFromDate,ValidToDate,SumInsured,Deductible,Status,Version) VALUES(@id,@h,@b,@number,@patient,@plan,@policy,@member,@from,@to,@sum,@ded,@status,1)",
        ("id", c.Id), ("number", c.Number), ("patient", c.PatientId), ("plan", c.PlanId), ("policy", c.PolicyNumber), ("member", c.MemberId), ("from", c.ValidFrom), ("to", c.ValidTo), ("sum", c.SumInsured), ("ded", c.Deductible), ("status", c.Status), H, Branch);
    public async Task UpdateCoverageAsync(Coverage c, CancellationToken ct)
    {
        if (await Execute("UPDATE insurance.Coverages SET Status=@status,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old", ("status", c.Status), ("new", c.Version), ("id", c.Id), H, ("old", c.Version - 1)) != 1) throw Conflict();
    }
    public Task<IReadOnlyList<Coverage>> ListCoveragesAsync(Guid? patientId, CancellationToken ct) => Query("SELECT Id,Number,PatientId,PlanId,PolicyNumber,MemberId,ValidFromDate,ValidToDate,SumInsured,Deductible,Status,Version FROM insurance.Coverages WHERE HospitalId=@h AND (@patient IS NULL OR PatientId=@patient) ORDER BY ValidToDate DESC", MapCoverage, H, ("patient", patientId)).ContinueWith(t => (IReadOnlyList<Coverage>)t.Result, ct);
    public Task<InsurancePlan?> FindInsurancePlanAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,PayerId,Code,Name,PolicyType,SumInsuredLimit FROM insurance.Plans WHERE HospitalId=@h AND Id=@id", MapPlan, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertInsurancePlanAsync(InsurancePlan p, CancellationToken ct) => Execute("INSERT INTO insurance.Plans(Id,HospitalId,PayerId,Code,Name,PolicyType,SumInsuredLimit) VALUES(@id,@h,@payer,@code,@name,@type,@limit)",
        ("id", p.Id), ("payer", p.PayerId), ("code", p.Code), ("name", p.Name), ("type", p.PolicyType), ("limit", p.SumInsuredLimit), H);
    public Task<Preauthorization?> FindPreauthAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,CoverageId,PatientId,DiagnosisCode,ProcedureCode,RequestedAmount,Status,ValidFromDate,ValidToDate,ApprovedAmount,ResponseNote,RespondedBy,RespondedAtUtc,RequestedBy,RequestedAtUtc,Version FROM insurance.Preauthorizations WHERE HospitalId=@h AND Id=@id", MapPreauth, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertPreauthAsync(Preauthorization p, CancellationToken ct) => Execute("INSERT INTO insurance.Preauthorizations(Id,HospitalId,BranchId,Number,CoverageId,PatientId,DiagnosisCode,ProcedureCode,RequestedAmount,Status,ValidFromDate,ValidToDate,ApprovedAmount,ResponseNote,RespondedBy,RespondedAtUtc,RequestedBy,RequestedAtUtc,Version) VALUES(@id,@h,@b,@number,@coverage,@patient,@diagnosis,@procedure,@amount,@status,@from,@to,@approved,@note,@rby,@rat,@by,@at,1)",
        ("id", p.Id), ("number", p.Number), ("coverage", p.CoverageId), ("patient", p.PatientId), ("diagnosis", p.DiagnosisCode), ("procedure", p.ProcedureCode), ("amount", p.RequestedAmount), ("status", p.Status), ("from", p.ValidFrom), ("to", p.ValidTo), ("approved", p.ApprovedAmount), ("note", p.ResponseNote), ("rby", p.RespondedBy), ("rat", p.RespondedAt?.UtcDateTime), ("by", p.RequestedBy), ("at", p.RequestedAt.UtcDateTime), H, Branch);
    public async Task UpdatePreauthAsync(Preauthorization p, CancellationToken ct)
    {
        if (await Execute("UPDATE insurance.Preauthorizations SET Status=@status,ApprovedAmount=@approved,ResponseNote=@note,RespondedBy=@rby,RespondedAtUtc=@rat,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status='Requested'",
            ("status", p.Status), ("approved", p.ApprovedAmount), ("note", p.ResponseNote), ("rby", p.RespondedBy), ("rat", p.RespondedAt?.UtcDateTime), ("new", p.Version), ("id", p.Id), H, ("old", p.Version - 1)) != 1) throw Conflict();
    }
    public Task<IReadOnlyList<Preauthorization>> ListPreauthsAsync(Guid? patientId, CancellationToken ct) => Query("SELECT Id,Number,CoverageId,PatientId,DiagnosisCode,ProcedureCode,RequestedAmount,Status,ValidFromDate,ValidToDate,ApprovedAmount,ResponseNote,RespondedBy,RespondedAtUtc,RequestedBy,RequestedAtUtc,Version FROM insurance.Preauthorizations WHERE HospitalId=@h AND (@patient IS NULL OR PatientId=@patient) ORDER BY RequestedAtUtc DESC", MapPreauth, H, ("patient", patientId)).ContinueWith(t => (IReadOnlyList<Preauthorization>)t.Result, ct);
    public Task<Claim?> FindClaimAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,CoverageId,InvoiceId,AdmissionId,DiagnosisCode,TotalAmount,ApprovedAmount,PatientLiability,Status,QueryNote,ResponseNote,RejectionReason,SubmittedBy,SubmittedAtUtc,CreatedBy,CreatedAtUtc,Version FROM insurance.Claims WHERE HospitalId=@h AND Id=@id", MapClaim, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task<Claim?> FindClaimByInvoiceAsync(Guid invoiceId, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,CoverageId,InvoiceId,AdmissionId,DiagnosisCode,TotalAmount,ApprovedAmount,PatientLiability,Status,QueryNote,ResponseNote,RejectionReason,SubmittedBy,SubmittedAtUtc,CreatedBy,CreatedAtUtc,Version FROM insurance.Claims WHERE HospitalId=@h AND InvoiceId=@invoice", MapClaim, H, ("invoice", invoiceId)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertClaimAsync(Claim c, CancellationToken ct) => Execute("INSERT INTO insurance.Claims(Id,HospitalId,BranchId,Number,PatientId,CoverageId,InvoiceId,AdmissionId,DiagnosisCode,TotalAmount,ApprovedAmount,PatientLiability,Status,QueryNote,ResponseNote,RejectionReason,SubmittedBy,SubmittedAtUtc,CreatedBy,CreatedAtUtc,Version) VALUES(@id,@h,@b,@number,@patient,@coverage,@invoice,@admission,@diagnosis,@total,@approved,@liability,@status,@query,@response,@rejection,@sby,@sat,@by,@at,1)",
        ("id", c.Id), ("number", c.Number), ("patient", c.PatientId), ("coverage", c.CoverageId), ("invoice", c.InvoiceId), ("admission", c.AdmissionId), ("diagnosis", c.DiagnosisCode), ("total", c.TotalAmount), ("approved", c.ApprovedAmount), ("liability", c.PatientLiability), ("status", c.Status), ("query", c.QueryNote), ("response", c.ResponseNote), ("rejection", c.RejectionReason), ("sby", c.SubmittedBy), ("sat", c.SubmittedAt?.UtcDateTime), ("by", c.CreatedBy), ("at", c.CreatedAt.UtcDateTime), H, Branch);
    public async Task UpdateClaimAsync(Claim c, CancellationToken ct)
    {
        if (await Execute("UPDATE insurance.Claims SET Status=@status,ApprovedAmount=@approved,PatientLiability=@liability,QueryNote=@query,ResponseNote=@response,RejectionReason=@rejection,SubmittedBy=@sby,SubmittedAtUtc=@sat,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status NOT IN ('Settled','Rejected')",
            ("status", c.Status), ("approved", c.ApprovedAmount), ("liability", c.PatientLiability), ("query", c.QueryNote), ("response", c.ResponseNote), ("rejection", c.RejectionReason), ("sby", c.SubmittedBy), ("sat", c.SubmittedAt?.UtcDateTime), ("new", c.Version), ("id", c.Id), H, ("old", c.Version - 1)) != 1) throw Conflict();
    }
    public Task<IReadOnlyList<Claim>> ListClaimsAsync(Guid? patientId, CancellationToken ct) => Query("SELECT Id,Number,PatientId,CoverageId,InvoiceId,AdmissionId,DiagnosisCode,TotalAmount,ApprovedAmount,PatientLiability,Status,QueryNote,ResponseNote,RejectionReason,SubmittedBy,SubmittedAtUtc,CreatedBy,CreatedAtUtc,Version FROM insurance.Claims WHERE HospitalId=@h AND (@patient IS NULL OR PatientId=@patient) ORDER BY CreatedAtUtc DESC", MapClaim, H, ("patient", patientId)).ContinueWith(t => (IReadOnlyList<Claim>)t.Result, ct);
    public Task InsertClaimLineAsync(ClaimLine l, CancellationToken ct) => Execute("INSERT INTO insurance.ClaimLines(Id,HospitalId,ClaimId,ServiceCode,Description,Quantity,UnitPrice,Amount,ApprovedAmount) VALUES(@id,@h,@claim,@code,@description,@qty,@price,@amount,@approved)",
        ("id", l.Id), ("claim", l.ClaimId), ("code", l.ServiceCode), ("description", l.Description), ("qty", l.Quantity), ("price", l.UnitPrice), ("amount", l.Amount), ("approved", l.ApprovedAmount), H);
    public Task<IReadOnlyList<ClaimLine>> ListClaimLinesAsync(Guid claimId, CancellationToken ct) => Query("SELECT Id,ClaimId,ServiceCode,Description,Quantity,UnitPrice,Amount,ApprovedAmount FROM insurance.ClaimLines WHERE HospitalId=@h AND ClaimId=@claim", MapClaimLine, H, ("claim", claimId)).ContinueWith(t => (IReadOnlyList<ClaimLine>)t.Result, ct);
    public Task InsertClaimQueryAsync(ClaimQuery q, CancellationToken ct) => Execute("INSERT INTO insurance.ClaimQueries(Id,HospitalId,ClaimId,Question,Response,RaisedBy,RaisedAtUtc,RespondedBy,RespondedAtUtc) VALUES(@id,@h,@claim,@question,@response,@by,@at,@rby,@rat)",
        ("id", q.Id), ("claim", q.ClaimId), ("question", q.Question), ("response", q.Response), ("by", q.RaisedBy), ("at", q.RaisedAt.UtcDateTime), ("rby", q.RespondedBy), ("rat", q.RespondedAt?.UtcDateTime), H);
    public Task UpdateClaimQueryAsync(ClaimQuery q, CancellationToken ct) => Execute("UPDATE insurance.ClaimQueries SET Response=@response,RespondedBy=@rby,RespondedAtUtc=@rat WHERE Id=@id AND HospitalId=@h",
        ("response", q.Response), ("rby", q.RespondedBy), ("rat", q.RespondedAt?.UtcDateTime), ("id", q.Id), H);
    public Task<IReadOnlyList<ClaimQuery>> ListClaimQueriesAsync(Guid claimId, CancellationToken ct) => Query("SELECT Id,ClaimId,Question,Response,RaisedBy,RaisedAtUtc,RespondedBy,RespondedAtUtc FROM insurance.ClaimQueries WHERE HospitalId=@h AND ClaimId=@claim ORDER BY RaisedAtUtc", MapClaimQuery, H, ("claim", claimId)).ContinueWith(t => (IReadOnlyList<ClaimQuery>)t.Result, ct);
