        ("id", s.Id), ("number", s.Number), ("claim", s.ClaimId), ("amount", s.Amount), ("mode", s.Mode), ("reference", s.Reference), ("at", s.SettledAt.UtcDateTime), ("by", s.SettledBy), H, Branch);
