        ("id", r.Id), ("name", r.Name), ("scope", r.ScopeKind), ("doctor", r.DoctorId), ("basis", r.Basis), ("mode", r.Mode), ("value", r.Value), ("from", r.EffectiveFrom), ("to", r.EffectiveTo), ("status", r.Status), ("by", r.CreatedBy), H);
