    public Task<bool> HasOverlappingIncentiveRuleAsync(string scopeKind, Guid? doctorId, string basis, DateOnly from, DateOnly? to, Guid? excludeId, CancellationToken ct) =>
        Query("SELECT COUNT(1) FROM incentive.Rules WHERE HospitalId=@h AND ScopeKind=@scope AND ((@doctor IS NULL AND DoctorId IS NULL) OR DoctorId=@doctor) AND Basis=@basis AND (@exclude IS NULL OR Id<>@exclude) AND @from <= COALESCE(@to, '2999-12-31') AND COALESCE(EffectiveToDate, '2999-12-31') >= @from",
            r => Convert.ToInt32(r[0]), H, ("scope", scopeKind), ("doctor", doctorId), ("basis", basis), ("exclude", excludeId), ("from", from), ("to", to)).ContinueWith(t => t.Result[0] > 0, ct);
    public Task<IReadOnlyList<IncentiveRule>> ListActiveIncentiveRulesAsync(DateOnly on, CancellationToken ct) => Query("SELECT Id,Name,ScopeKind,DoctorId,Basis,Mode,RuleValue,EffectiveFromDate,EffectiveToDate,Status,CreatedBy,Version FROM incentive.Rules WHERE HospitalId=@h AND Status='Active' AND EffectiveFromDate<=@on AND (EffectiveToDate IS NULL OR EffectiveToDate>=@on)", MapRule, H, ("on", on)).ContinueWith(t => (IReadOnlyList<IncentiveRule>)t.Result, ct);
