    public async Task<IReadOnlyList<IncentiveEvent>> ListIncentiveEventsAsync(DateOnly from, DateOnly to, CancellationToken ct)
    {
        var events = new List<IncentiveEvent>();
        events.AddRange(await Query("SELECT e.DoctorId,CAST(e.Id AS nvarchar(36)) AS Ref,0 AS Amount,e.StartedAtUtc AS AtUtc FROM emr.Encounters e WHERE e.HospitalId=@h AND e.Status='Signed' AND CAST(e.UpdatedAtUtc AS date) BETWEEN @from AND @to",
            r => new IncentiveEvent("Consultation", G(r, "DoctorId"), S(r, "Ref"), 0m, T(r, "AtUtc")), H, ("from", from), ("to", to)));
        events.AddRange(await Query("SELECT e.DoctorId,CAST(p.Id AS nvarchar(36)) AS Ref,p.Amount,p.ReceivedAtUtc AS AtUtc FROM bill.Payments p JOIN bill.Invoices i ON i.Id=p.InvoiceId AND i.HospitalId=p.HospitalId CROSS APPLY (SELECT TOP(1) DoctorId FROM emr.Encounters e WHERE e.HospitalId=p.HospitalId AND e.PatientId=i.PatientId AND e.Status='Signed' AND e.UpdatedAtUtc<=p.ReceivedAtUtc ORDER BY e.UpdatedAtUtc DESC) e WHERE p.HospitalId=@h AND CAST(p.ReceivedAtUtc AS date) BETWEEN @from AND @to",
            r => new IncentiveEvent("Revenue", G(r, "DoctorId"), S(r, "Ref"), DN(r, "Amount")!.Value, T(r, "AtUtc")), H, ("from", from), ("to", to)));
        events.AddRange(await Query("SELECT b.SurgeonId AS DoctorId,CAST(b.Id AS nvarchar(36)) AS Ref,0 AS Amount,b.ScheduledStartUtc AS AtUtc FROM ot.Bookings b WHERE b.HospitalId=@h AND b.Status='Completed' AND CAST(b.ScheduledStartUtc AS date) BETWEEN @from AND @to",
            r => new IncentiveEvent("Surgery", G(r, "DoctorId"), S(r, "Ref"), 0m, T(r, "AtUtc")), H, ("from", from), ("to", to)));
        events.AddRange(await Query("SELECT e.DoctorId,CAST(r.Id AS nvarchar(36)) AS Ref,0 AS Amount,r.AuthorizedAtUtc AS AtUtc FROM ris.Reports r JOIN ris.Orders o ON o.Id=r.OrderId AND o.HospitalId=r.HospitalId CROSS APPLY (SELECT TOP(1) DoctorId FROM emr.Encounters e WHERE e.HospitalId=r.HospitalId AND e.PatientId=o.PatientId AND e.Status='Signed' AND e.UpdatedAtUtc<=r.AuthorizedAtUtc ORDER BY e.UpdatedAtUtc DESC) e WHERE r.HospitalId=@h AND CAST(r.AuthorizedAtUtc AS date) BETWEEN @from AND @to",
            r => new IncentiveEvent("Procedure", G(r, "DoctorId"), S(r, "Ref"), 0m, T(r, "AtUtc")), H, ("from", from), ("to", to)));
        return events;
    }

