        ("id", s.Id), ("number", s.Number), ("appointment", s.AppointmentId), ("patient", s.PatientId), ("doctor", s.DoctorId), ("status", s.Status), ("at", s.ScheduledAt.UtcDateTime), ("consent", s.ConsentObtained), ("start", s.StartedAt?.UtcDateTime), ("end", s.EndedAt?.UtcDateTime), ("note", s.EndNote), ("advice", s.EmergencyAdvice), H, Branch);
