    public Task<Asset?> FindAssetBySerialAsync(string serial, CancellationToken ct) => Query("SELECT TOP(1) Id,Tag,ItemId,SerialNumber,Status,Custodian,RecordedBy,AtUtc FROM inventory.Assets WHERE HospitalId=@h AND SerialNumber=@serial", MapAsset, H, ("serial", serial)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
