    // ---- CSSD ---------------------------------------------------------------
    private static InstrumentSet MapSet(DbDataReader r) => new(G(r, "Id"), S(r, "Code"), S(r, "Name"), S(r, "Status"), I(r, "MissingCount"), TN(r, "SterileExpiryUtc"), GN(r, "LastCycleId"), L(r, "Version"));
    private static InstrumentItem MapSetItem(DbDataReader r) => new(G(r, "Id"), G(r, "SetId"), S(r, "Name"), S(r, "SerialNumber"), S(r, "Condition"));
    private static SterilizerCycle MapCycle(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), S(r, "Method"), S(r, "Machine"), DN(r, "TempC")!.Value, I(r, "DurationMin"), S(r, "Status"), T(r, "StartedAtUtc"), TN(r, "EndedAtUtc"), G(r, "OperatorBy"), L(r, "Version"));
    private static CycleLoad MapCycleLoad(DbDataReader r) => new(G(r, "Id"), G(r, "CycleId"), G(r, "SetId"), S(r, "SetStatus"));
    private static CycleIndicator MapIndicator(DbDataReader r) => new(G(r, "Id"), G(r, "CycleId"), S(r, "Kind"), S(r, "Result"), S(r, "Note"), G(r, "RecordedBy"), T(r, "AtUtc"));
    private static CssdIssue MapCssdIssue(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "SetId"), GN(r, "BookingId"), S(r, "IssuedTo"), S(r, "Status"), S(r, "ReturnCondition"), T(r, "IssuedAtUtc"), G(r, "IssuedBy"), TN(r, "ReturnedAtUtc"), L(r, "Version"));
    private static CssdRecall MapRecall(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "CycleId"), S(r, "Reason"), S(r, "Status"), G(r, "OpenedBy"), T(r, "AtUtc"));

    public Task<InstrumentSet?> FindInstrumentSetAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Code,Name,Status,MissingCount,SterileExpiryUtc,LastCycleId,Version FROM cssd.Sets WHERE HospitalId=@h AND Id=@id", MapSet, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertInstrumentSetAsync(InstrumentSet s, CancellationToken ct) => Execute("INSERT INTO cssd.Sets(Id,HospitalId,Code,Name,Status,MissingCount,SterileExpiryUtc,LastCycleId,Version) VALUES(@id,@h,@code,@name,@status,@missing,@expiry,@cycle,1)",
        ("id", s.Id), ("code", s.Code), ("name", s.Name), ("status", s.Status), ("missing", s.MissingCount), ("expiry", s.SterileExpiry?.UtcDateTime), ("cycle", s.LastCycleId), H);
    public async Task UpdateInstrumentSetAsync(InstrumentSet s, CancellationToken ct)
    {
        if (await Execute("UPDATE cssd.Sets SET Status=@status,MissingCount=@missing,SterileExpiryUtc=@expiry,LastCycleId=@cycle,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old",
            ("status", s.Status), ("missing", s.MissingCount), ("expiry", s.SterileExpiry?.UtcDateTime), ("cycle", s.LastCycleId), ("new", s.Version), ("id", s.Id), H, ("old", s.Version - 1)) != 1) throw Conflict();
    }
    public Task<IReadOnlyList<InstrumentSet>> ListInstrumentSetsAsync(CancellationToken ct) => Query("SELECT Id,Code,Name,Status,MissingCount,SterileExpiryUtc,LastCycleId,Version FROM cssd.Sets WHERE HospitalId=@h ORDER BY Code", MapSet, H).ContinueWith(t => (IReadOnlyList<InstrumentSet>)t.Result, ct);
    public Task InsertInstrumentItemAsync(InstrumentItem i, CancellationToken ct) => Execute("INSERT INTO cssd.SetItems(Id,HospitalId,SetId,Name,SerialNumber,Condition) VALUES(@id,@h,@set,@name,@serial,@condition)",
        ("id", i.Id), ("set", i.SetId), ("name", i.Name), ("serial", i.SerialNumber), ("condition", i.Condition), H);
    public Task<IReadOnlyList<InstrumentItem>> ListInstrumentItemsAsync(Guid setId, CancellationToken ct) => Query("SELECT Id,SetId,Name,SerialNumber,Condition FROM cssd.SetItems WHERE HospitalId=@h AND SetId=@set", MapSetItem, H, ("set", setId)).ContinueWith(t => (IReadOnlyList<InstrumentItem>)t.Result, ct);
    public Task<SterilizerCycle?> FindCycleAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,Method,Machine,TempC,DurationMin,Status,StartedAtUtc,EndedAtUtc,OperatorBy,Version FROM cssd.Cycles WHERE HospitalId=@h AND Id=@id", MapCycle, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertCycleAsync(SterilizerCycle c, CancellationToken ct) => Execute("INSERT INTO cssd.Cycles(Id,HospitalId,BranchId,Number,Method,Machine,TempC,DurationMin,Status,StartedAtUtc,EndedAtUtc,OperatorBy,Version) VALUES(@id,@h,@b,@number,@method,@machine,@temp,@duration,@status,@start,@end,@operator,1)",
        ("id", c.Id), ("number", c.Number), ("method", c.Method), ("machine", c.Machine), ("temp", c.TempC), ("duration", c.DurationMin), ("status", c.Status), ("start", c.StartedAt.UtcDateTime), ("end", c.EndedAt?.UtcDateTime), ("operator", c.Operator), H, Branch);
    public async Task UpdateCycleAsync(SterilizerCycle c, CancellationToken ct)
    {
        if (await Execute("UPDATE cssd.Cycles SET Status=@status,EndedAtUtc=@end,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old AND Status NOT IN ('Passed','Failed')",
            ("status", c.Status), ("end", c.EndedAt?.UtcDateTime), ("new", c.Version), ("id", c.Id), H, ("old", c.Version - 1)) != 1) throw Conflict();
    }
    public Task<IReadOnlyList<SterilizerCycle>> ListCyclesAsync(CancellationToken ct) => Query("SELECT Id,Number,Method,Machine,TempC,DurationMin,Status,StartedAtUtc,EndedAtUtc,OperatorBy,Version FROM cssd.Cycles WHERE HospitalId=@h ORDER BY StartedAtUtc DESC", MapCycle, H).ContinueWith(t => (IReadOnlyList<SterilizerCycle>)t.Result, ct);
    public Task InsertCycleLoadAsync(CycleLoad l, CancellationToken ct) => Execute("INSERT INTO cssd.CycleLoads(Id,HospitalId,CycleId,SetId,SetStatus) VALUES(@id,@h,@cycle,@set,@status)", ("id", l.Id), ("cycle", l.CycleId), ("set", l.SetId), ("status", l.SetStatus), H);
