    public Task<CssdIssue?> FindCssdIssueAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,SetId,BookingId,IssuedTo,Status,ReturnCondition,IssuedAtUtc,IssuedBy,ReturnedAtUtc,Version FROM cssd.Issues WHERE HospitalId=@h AND Id=@id", MapCssdIssue, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertCssdIssueAsync(CssdIssue i, CancellationToken ct) => Execute("INSERT INTO cssd.Issues(Id,HospitalId,BranchId,Number,SetId,BookingId,IssuedTo,Status,ReturnCondition,IssuedAtUtc,IssuedBy,ReturnedAtUtc,Version) VALUES(@id,@h,@b,@number,@set,@booking,@issuedTo,@status,@condition,@at,@by,NULL,1)",
        ("id", i.Id), ("number", i.Number), ("set", i.SetId), ("booking", i.BookingId), ("issuedTo", i.IssuedTo), ("status", i.Status), ("condition", i.ReturnCondition), ("at", i.IssuedAt.UtcDateTime), ("by", i.IssuedBy), H, Branch);
