    public Task<IReadOnlyList<CssdIssue>> ListCssdIssuesBySetAsync(Guid setId, CancellationToken ct) => Query("SELECT Id,Number,SetId,BookingId,IssuedTo,Status,ReturnCondition,IssuedAtUtc,IssuedBy,ReturnedAtUtc,Version FROM cssd.Issues WHERE HospitalId=@h AND SetId=@set ORDER BY IssuedAtUtc DESC", MapCssdIssue, H, ("set", setId)).ContinueWith(t => (IReadOnlyList<CssdIssue>)t.Result, ct);
